test('invoiceTotals calculates VAT correctly', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // subtotal = 100000
  // discount = 0
  // vat = 100000 * 21 / 100 = 21000
  // total = 100000 - 0 + 21000 = 121000
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 21000);
  assert.equal(totals.total, 121000);
});

test('invoiceTotals sums VAT from multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
      { qty: 100, unitPrice: 1000, vatRate: 9, discountPercent: 0 },
      { qty: 100, unitPrice: 1000, vatRate: 0, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: 100000 * 21 / 100 = 21000
  // Line 2: 100000 * 9 / 100 = 9000
  // Line 3: 100000 * 0 / 100 = 0
  // Total VAT = 30000
  // Total = 300000 - 0 + 30000 = 330000
  assert.equal(totals.subtotal, 300000);
  assert.equal(totals.vat, 30000);
  assert.equal(totals.total, 330000);
});

test('invoiceTotals with discount affects VAT calculation', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 10 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // subtotal = 100000
  // discount = 10000
  // amountAfterDiscount = 90000
  // vat = 90000 * 21 / 100 = 18900
  // total = 100000 - 10000 + 18900 = 108900
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 10000);
  assert.equal(totals.vat, 18900);
  assert.equal(totals.total, 108900);
});

test('invoiceTotals total formula: subtotal - discount + vat', () => {
  const invoice = {
    lines: [
      { qty: 50, unitPrice: 9500, vatRate: 21, discountPercent: 5 },
      { qty: 10, unitPrice: 37, vatRate: 9, discountPercent: 10 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: total=475000, discount=23750, afterDiscount=451250, vat=94762 (rounded)
  // Line 2: total=370, discount=37, afterDiscount=333, vat=30 (rounded, 333*9/100=29.97->30)
  // subtotal = 475370
  // discount = 23787
  // vat = 94792
  // total = 475370 - 23787 + 94792 = 546375

  assert.equal(totals.subtotal, 475370);
  assert.equal(totals.discount, 23787);
  assert.equal(totals.vat, 94792);
  assert.equal(totals.total, 546375);
});

