});

test('lineTotal works with large numbers', () => {
  assert.equal(lineTotal({ qty: 1000, unitPrice: 999900 }), 999900000);
});

test('invoiceTotals calculates subtotal and total from a single line', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // subtotal = 47500, discount = 0, vat = 47500 * 21 / 100 = 9975, total = 47500 + 9975 = 57475
  assert.deepEqual(totals, { subtotal: 47500, discount: 0, vat: 9975, total: 57475 });
});

test('invoiceTotals sums all line totals', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 120000, discountPercent: 0, vatRate: 21 },
      { qty: 100, unitPrice: 37, discountPercent: 0, vatRate: 9 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // line1: subtotal=47500, vat=47500*21/100=9975
  // line2: subtotal=120000, vat=120000*21/100=25200
  // line3: subtotal=3700, vat=3700*9/100=333
  // total vat = 35508, total = 171200 + 35508 = 206708
  assert.equal(totals.subtotal, 47500 + 120000 + 3700);
  assert.equal(totals.vat, 9975 + 25200 + 333);
  assert.equal(totals.subtotal, 171200);
  assert.equal(totals.total, 206708);
});

