test('lineTotal multiplies quantity by unit price', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 9500 }), 9500);
  assert.equal(lineTotal({ qty: 5, unitPrice: 9500 }), 47500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 37 }), 3700);
});

test('lineTotal works with zero quantity', () => {
  assert.equal(lineTotal({ qty: 0, unitPrice: 9500 }), 0);
});

test('lineTotal works with large numbers', () => {
  assert.equal(lineTotal({ qty: 1000, unitPrice: 999900 }), 999900000);
});

test('invoiceTotals calculates subtotal and total from a single line', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // subtotal = 47500, discount = 0, vat = 47500 * 21 / 100 = 9975, total = 47500 + 9975 = 57475
  assert.deepEqual(totals, { subtotal: 47500, discount: 0, vat: 9975, total: 57475 });
});

test('invoiceTotals sums all line totals', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 120000, discountPercent: 0, vatRate: 21 },
      { qty: 100, unitPrice: 37, discountPercent: 0, vatRate: 9 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // line1: subtotal=47500, vat=47500*21/100=9975
  // line2: subtotal=120000, vat=120000*21/100=25200
  // line3: subtotal=3700, vat=3700*9/100=333
  // total vat = 35508, total = 171200 + 35508 = 206708
  assert.equal(totals.subtotal, 47500 + 120000 + 3700);
  assert.equal(totals.vat, 9975 + 25200 + 333);
  assert.equal(totals.subtotal, 171200);
  assert.equal(totals.total, 206708);
});

test('invoiceTotals handles empty lines', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 0, discount: 0, vat: 0, total: 0 });
});

test('invoiceTotals matches createInvoice result', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002', // standard tier (0% discount)
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;
  const totals = invoiceTotals(invoice);

  const expectedDev = 5 * 9500;
  const expectedLogo = 1 * 120000;
  // Both have vatRate 21
  const expectedVAT = expectedDev * 0.21 + expectedLogo * 0.21;
  assert.equal(totals.subtotal, expectedDev + expectedLogo);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, expectedDev + expectedLogo + expectedVAT);
});

test('invoiceTotals does not mutate the invoice', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500 },
      { qty: 1, unitPrice: 120000 },
    ],
  };

  const invoiceCopy = JSON.parse(JSON.stringify(invoice));

  invoiceTotals(invoice);

  assert.deepEqual(invoice, invoiceCopy);
});

test('invoiceTotals with no discount returns { subtotal, discount: 0, total }', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, discountPercent: 0 },
      { qty: 1, unitPrice: 120000, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 167500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 167500);
});

test('invoiceTotals with discount applies percentage to line totals', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 9500, discountPercent: 10 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // subtotal = 100 * 9500 = 950000
  // discount = 950000 * 10 / 100 = 95000
  // total = 950000 - 95000 = 855000
  assert.equal(totals.subtotal, 950000);
  assert.equal(totals.discount, 95000);
  assert.equal(totals.total, 855000);
});

test('invoiceTotals with multiple lines and different discounts', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, discountPercent: 10 },
      { qty: 1, unitPrice: 120000, discountPercent: 20 },
      { qty: 100, unitPrice: 1000, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // line 1: 5 * 9500 = 47500, discount = 4750, after = 42750
  // line 2: 1 * 120000 = 120000, discount = 24000, after = 96000
  // line 3: 100 * 1000 = 100000, discount = 0, after = 100000
  // subtotal = 267500, discount = 28750, total = 238750
  assert.equal(totals.subtotal, 267500);
  assert.equal(totals.discount, 28750);
  assert.equal(totals.total, 238750);
});

test('invoiceTotals with 100% discount on a line', () => {
