test('lineVAT with different VAT rates', () => {
  const line21 = {
    qty: 100,
    unitPrice: 1000,
    vatRate: 21,
    discountPercent: 0,
  };

  const line9 = {
    qty: 100,
    unitPrice: 1000,
    vatRate: 9,
    discountPercent: 0,
  };

  const line0 = {
    qty: 100,
    unitPrice: 1000,
    vatRate: 0,
    discountPercent: 0,
  };

  // All have lineTotal = 100000
  assert.equal(lineVAT(line21), 21000); // 100000 * 21 / 100
  assert.equal(lineVAT(line9), 9000); // 100000 * 9 / 100
  assert.equal(lineVAT(line0), 0); // 100000 * 0 / 100
});

test('invoiceTotals includes vat field', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.ok('vat' in totals);
