  };

  const invoiceCopy = JSON.parse(JSON.stringify(invoice));

  invoiceTotals(invoice);

  assert.deepEqual(invoice, invoiceCopy);
});

test('invoiceTotals with no discount returns { subtotal, discount: 0, vat, total }', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 120000, discountPercent: 0, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // vat = (47500 + 120000) * 0.21 = 35175
  // total = 167500 + 35175 = 202675
  assert.equal(totals.subtotal, 167500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 35175);
  assert.equal(totals.total, 202675);
});

test('invoiceTotals with discount applies percentage to line totals', () => {
