  const totals = invoiceTotals(invoice);
  // line 1: 5 * 9500 = 47500, discount = 4750, afterDiscount = 42750, vat = 42750*21/100 = 8977.5 -> 8978
  // line 2: 1 * 120000 = 120000, discount = 24000, afterDiscount = 96000, vat = 96000*21/100 = 20160
  // line 3: 100 * 1000 = 100000, discount = 0, afterDiscount = 100000, vat = 0
  // subtotal = 267500, discount = 28750, vat = 29138, total = 267500 - 28750 + 29138 = 267888
  assert.equal(totals.subtotal, 267500);
  assert.equal(totals.discount, 28750);
  assert.equal(totals.vat, 29138);
  assert.equal(totals.total, 267888);
