});

test('invoiceTotals total formula: subtotal - discount + vat', () => {
  const invoice = {
    lines: [
      { qty: 50, unitPrice: 9500, vatRate: 21, discountPercent: 5 },
      { qty: 10, unitPrice: 37, vatRate: 9, discountPercent: 10 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: total=475000, discount=23750, afterDiscount=451250, vat=94762 (rounded)
  // Line 2: total=370, discount=37, afterDiscount=333, vat=30 (rounded, 333*9/100=29.97->30)
  // subtotal = 475370
  // discount = 23787
  // vat = 94792
  // total = 475370 - 23787 + 94792 = 546375

  assert.equal(totals.subtotal, 475370);
  assert.equal(totals.discount, 23787);
  assert.equal(totals.vat, 94792);
  assert.equal(totals.total, 546375);
