  const withNewLine = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 }).value;
  assert.equal(withNewLine.customerId, 'C-001');
  assert.equal(withNewLine.issueDate, '2026-10-07');
  assert.equal(withNewLine.status, 'draft');

  const withoutLine = removeLine(withNewLine, 'LOGO-PACK').value;
  assert.equal(withoutLine.customerId, 'C-001');
