  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', qty: 100, name: 'Development (hour)', unitPrice: 9500, vatRate: 21, discountPercent: 0 },
    ],
  };

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  // Should have: number, customer, invoice line, VAT, total
  assert.equal(lines.length, 5);
  assert.ok(lines[3].startsWith('VAT:'));
  assert.ok(lines[4].startsWith('Total:'));
});

test('renderInvoiceText calculates VAT with discount', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', qty: 100, name: 'Development (hour)', unitPrice: 9500, vatRate: 21, discountPercent: 10 },
    ],
  };

  const text = renderInvoiceText(invoice);
  // subtotal = 950000
  // discount = 95000
  // amountAfterDiscount = 855000
  // vat = 855000 * 21 / 100 = 179550 = €1,795.50
  // total = 950000 - 95000 + 179550 = 1034550 = €10,345.50

  assert.ok(text.includes('VAT: €1,795.50'));
  assert.ok(text.includes('Total: €10,345.50'));
});

test('renderInvoiceText with mixed VAT rates', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, name: 'Development (hour)', unitPrice: 9500, vatRate: 21, discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 500, name: 'Printed flyer A4 (each)', unitPrice: 37, vatRate: 9, discountPercent: 0 },
    ],
  };

  const text = renderInvoiceText(invoice);
  // Line 1: 95000, VAT = 95000 * 21 / 100 = 19950
  // Line 2: 18500, VAT = 18500 * 9 / 100 = 1665
  // Total VAT = 21615 = €216.15
  // Total = 95000 + 18500 - 0 + 21615 = 135115 = €1,351.15

  assert.ok(text.includes('VAT: €216.15'));
  assert.ok(text.includes('Total: €1,351.15'));
});

