test('renderInvoiceText calculates VAT with discount', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', qty: 100, name: 'Development (hour)', unitPrice: 9500, vatRate: 21, discountPercent: 10 },
    ],
  };

  const text = renderInvoiceText(invoice);
  // subtotal = 950000
  // discount = 95000
  // amountAfterDiscount = 855000
  // vat = 855000 * 21 / 100 = 179550 = €1,795.50
  // total = 950000 - 95000 + 179550 = 1034550 = €10,345.50

  assert.ok(text.includes('VAT: €1,795.50'));
  assert.ok(text.includes('Total: €10,345.50'));
});

test('renderInvoiceText with mixed VAT rates', () => {
