    ],
  };

  const text = renderInvoiceText(invoice);
  // Line 1: 95000, VAT = 95000 * 21 / 100 = 19950
  // Line 2: 18500, VAT = 18500 * 9 / 100 = 1665
  // Total VAT = 21615 = €216.15
  // Total = 95000 + 18500 - 0 + 21615 = 135115 = €1,351.15

  assert.ok(text.includes('VAT: €216.15'));
  assert.ok(text.includes('Total: €1,351.15'));
});

