  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2026-0042');
  assert.equal(lines[1], 'Kite & Co');

  // Check all three invoice lines exist
  assert.ok(lines[2].includes('10'));
  assert.ok(lines[2].includes('Development (hour)'));
  assert.ok(lines[3].includes('5'));
  assert.ok(lines[3].includes('Design work (hour)'));
  assert.ok(lines[4].includes('500'));
  assert.ok(lines[4].includes('Printed flyer A4 (each)'));

  // Verify total with VAT:
  // line1: 95000, discount=2375, after=92625, vat=roundCents(19451.25)=19451
  // line2: 42500, discount=1062, after=41438, vat=roundCents(8701.98)=8702
  // line3: 18500, discount=462, after=18038, vat=roundCents(1623.42)=1623
  // subtotal = 156000, discount=3899, vat=29776, total = 156000-3899+29776 = 181877
  assert.ok(lines[5].startsWith('VAT:'));
  assert.ok(lines[6].includes('Total: €1,818.77'));
});

